import{_ as n,o as d,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"BrandHub — Jira Status Audit","description":"","frontmatter":{},"headers":[],"relativePath":"plan/audit/jira-status-audit-2026-07-11.md","filePath":"plan/audit/jira-status-audit-2026-07-11.md"}'),i={name:"plan/audit/jira-status-audit-2026-07-11.md"};function h(e,t,o,g,s,c){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="brandhub-—-jira-status-audit" tabindex="-1">BrandHub — Jira Status Audit <a class="header-anchor" href="#brandhub-—-jira-status-audit" aria-label="Permalink to &quot;BrandHub — Jira Status Audit&quot;">​</a></h1><p>&gt; Nguồn: Jira project <code>DA</code> — <a href="https://letritrung2605.atlassian.net" target="_blank" rel="noreferrer">https://letritrung2605.atlassian.net</a> &gt; Phạm vi: issuetype = Task (không tính Epic, Subtask, Bug) &gt; Cập nhật lần 2 — số liệu đã đối soát lại toàn bộ 406 task (lần audit đầu bị lỗi đếm do cursor phân trang sai, dẫn đến tổng ảo 455 và unassigned ảo 221 — số đúng là 406 / 172)</p><hr><h2 id="_1-tong-quan-theo-status" tabindex="-1">1. Tổng quan theo Status <a class="header-anchor" href="#_1-tong-quan-theo-status" aria-label="Permalink to &quot;1. Tổng quan theo Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Số lượng</th><th>Tỉ lệ</th></tr></thead><tbody><tr><td>To Do — có assignee</td><td>122</td><td>30.0%</td></tr><tr><td>To Do — <strong>chưa assign</strong></td><td>172</td><td>42.4%</td></tr><tr><td>In Review</td><td>46</td><td>11.3%</td></tr><tr><td>In Progress</td><td>8</td><td>2.0%</td></tr><tr><td>Done</td><td>58</td><td>14.3%</td></tr><tr><td><strong>Tổng</strong></td><td><strong>406</strong></td><td>100%</td></tr></tbody></table><p><strong>Đọc nhanh:</strong> 14.3% công việc hoàn thành. 42.4% backlog <strong>chưa có ai phụ trách</strong>. Đây vẫn là rủi ro lớn nhất, dù tỉ lệ thấp hơn số đã báo cáo lần trước.</p><hr><h2 id="_2-ma-tran-theo-thanh-vien-×-status" tabindex="-1">2. Ma trận theo thành viên × Status <a class="header-anchor" href="#_2-ma-tran-theo-thanh-vien-×-status" aria-label="Permalink to &quot;2. Ma trận theo thành viên × Status&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thành viên</th><th>To Do</th><th>In Review</th><th>In Progress</th><th>Done</th><th>Tổng</th><th>Tỉ lệ Done</th></tr></thead><tbody><tr><td>Trung</td><td>39</td><td>13</td><td>2</td><td>23</td><td>77</td><td>29.9%</td></tr><tr><td>Lộc</td><td>23</td><td>3</td><td>4</td><td>11</td><td>41</td><td>26.8%</td></tr><tr><td>Ân</td><td>24</td><td>8</td><td>1</td><td>7</td><td>40</td><td>17.5%</td></tr><tr><td>Tuấn</td><td>16</td><td>11</td><td>1</td><td>7</td><td>35</td><td>20.0%</td></tr><tr><td>Phước</td><td>20</td><td>11</td><td>0</td><td>3</td><td>34</td><td>8.8%</td></tr><tr><td>Team (chung)</td><td>0</td><td>0</td><td>0</td><td>7</td><td>7</td><td>100%</td></tr><tr><td><strong>Chưa assign</strong></td><td>172</td><td>—</td><td>—</td><td>—</td><td>172</td><td>—</td></tr><tr><td><strong>Tổng</strong></td><td>294</td><td>46</td><td>8</td><td>58</td><td>406</td><td>14.3%</td></tr></tbody></table><p><strong>Nhận xét:</strong></p><ul><li>Trung gánh khối lượng lớn nhất (77 task, ~19% tổng dự án) — đúng vai trò leader nhưng cũng là điểm nghẽn tiềm ẩn nếu Trung bận việc quản lý</li><li><strong>Phước</strong>: 0 task In Progress, Done thấp nhất (8.8%) — nhưng có 11 task đang In Review, nhiều thứ 2 sau Trung. Không hẳn trễ — phần lớn task Publisher Service theo plan gốc chỉ bắt đầu Sprint 7-8, team hiện ở Sprint 3-4</li><li><strong>Ân</strong>: Done thấp nhất về tỉ lệ trong nhóm có việc từ đầu (17.5%) — cần theo dõi</li></ul><hr><h2 id="_3-in-progress-—-chi-tiet-8-tasks" tabindex="-1">3. In Progress — chi tiết (8 tasks) <a class="header-anchor" href="#_3-in-progress-—-chi-tiet-8-tasks" aria-label="Permalink to &quot;3. In Progress — chi tiết (8 tasks)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Task</th><th>Assignee</th></tr></thead><tbody><tr><td>DA-358</td><td>[DA-AI09-05] Video generate endpoint</td><td>Ân</td></tr><tr><td>DA-328</td><td>[DA-AI09-03] Movement parameter mapping</td><td>Ân</td></tr><tr><td>DA-313</td><td>[DA-AI09-02] Video prompt template system</td><td>Ân</td></tr><tr><td>DA-299</td><td>[DA-AI09-06] Upload video to S3 + thumbnail</td><td>Ân</td></tr><tr><td>DA-451</td><td>[DA-E47-27] Team sprint report — Sprint 4</td><td>Trung</td></tr><tr><td>DA-446</td><td>[DA-E47-22] Individual sprint report — Sprint 4</td><td>Trung</td></tr><tr><td>DA-537</td><td>[DA-E48-01] AI iteration report — Iteration 1</td><td>Tuấn</td></tr><tr><td>DA-423</td><td>[DA-E09-12] Register brandhub domain (phát sinh)</td><td>Lộc</td></tr></tbody></table><p>4/8 task In Progress đều của Ân, tất cả thuộc AI09 (Video Generation) — đúng 1 chuỗi công việc liên tục, hợp lý không phải dàn trải nhiều việc cùng lúc.</p><hr><h2 id="_4-task-phat-sinh-—-khong-co-trong-brandhub-task-details-md" tabindex="-1">4. Task phát sinh — không có trong <code>BrandHub_Task_Details.md</code> <a class="header-anchor" href="#_4-task-phat-sinh-—-khong-co-trong-brandhub-task-details-md" aria-label="Permalink to &quot;4. Task phát sinh — không có trong `BrandHub_Task_Details.md`&quot;">​</a></h2><p>So khớp toàn bộ 406 task Jira với plan gốc (415 task ID định nghĩa sẵn). Phát hiện <strong>10 task thật sự phát sinh</strong> ngoài plan (loại trừ các task cũ DA-1 đến DA-144 chỉ thiếu format <code>[DA-XXX]</code> trong summary — bản thân chúng khớp plan, chỉ là style đặt tên lúc đầu dự án).</p><table tabindex="0"><thead><tr><th>Key</th><th>Task</th><th>Status</th><th>Assignee</th><th>Sprint/Epic gốc gần nhất</th><th>Ghi chú</th></tr></thead><tbody><tr><td>DA-405</td><td>[DA-E08-05] Create a view local document website automation</td><td>Done</td><td>Lộc</td><td>E08 (UI/UX Wireframe)</td><td>Không có trong plan gốc — tooling phụ, hợp lý</td></tr><tr><td>DA-407</td><td>[DA-E010-07] Create landing page UI</td><td>Done</td><td>Lộc</td><td>E10 (đánh số nhầm &quot;E010&quot;)</td><td>Landing page không nằm trong scope 46 epic gốc</td></tr><tr><td>DA-408</td><td>Create git-commit-convention rule</td><td>Done</td><td>Trung</td><td>— (không gắn epic)</td><td>Housekeeping, hợp lý phát sinh sớm</td></tr><tr><td>DA-409</td><td>[DA-E08-08] Integrated .html for view document</td><td>Done</td><td>Trung</td><td>E08</td><td>Liên quan DA-405, tooling doc site</td></tr><tr><td>DA-410</td><td>Research Google OMI API: capabilities, pricing, rate limits...</td><td>Done</td><td>Ân</td><td>Gần AI-01 (research)</td><td>Google OMI không nằm trong tech stack gốc (Veo được chọn) — cần xác nhận đây có phải hướng nghiên cứu mới hay nhầm với Veo</td></tr><tr><td>DA-423</td><td>[DA-E09-12] Register brandhub domain</td><td>In Progress</td><td>Lộc</td><td>E09 (Dev Environment)</td><td>Hợp lý — cần domain cho deploy/demo</td></tr><tr><td>DA-558</td><td>[DA-E09-13] Update diagram, dbml and html file for database</td><td>In Review</td><td>Trung</td><td>E09/E06</td><td>Bảo trì tài liệu DB sau khi schema đổi (users/workspaces chuyển sang PostgreSQL)</td></tr><tr><td>DA-559</td><td>[DA-E11-14] Add all model from database for business repo + repository files</td><td>Done</td><td>Trung</td><td>E11 (API Gateway) — <strong>gắn nhầm epic</strong>, thực chất là business-service JPA layer</td><td>Code thật đã chạy, đúng hướng nhưng lại gắn epic E11 (Gateway) thay vì phải là epic riêng cho business-service data layer</td></tr><tr><td>DA-560</td><td>[DA-E12-07] Research the HS256 vs RS256 vs ES256</td><td>In Review</td><td>Trung</td><td>E12 (Authentication)</td><td>Hợp lý — quyết định thuật toán JWT trước khi code Auth</td></tr><tr><td>DA-561</td><td>[Da-AI05-07] Brainstorm AI crawl idea</td><td>In Review</td><td>Trung</td><td>AI05 (Trend Crawler)</td><td>Có lỗi chính tả prefix &quot;Da-&quot; thay vì &quot;DA-&quot;; nội dung hợp lý mở rộng AI05</td></tr><tr><td>DA-562</td><td>test slack</td><td>To Do</td><td>Tuấn</td><td>—</td><td><strong>Rác — không phải task dự án thật, cần xoá</strong></td></tr></tbody></table><h3 id="nhan-xet-ve-task-phat-sinh" tabindex="-1">Nhận xét về task phát sinh <a class="header-anchor" href="#nhan-xet-ve-task-phat-sinh" aria-label="Permalink to &quot;Nhận xét về task phát sinh&quot;">​</a></h3><ul><li><strong>9/10 task phát sinh hợp lý</strong> — đa số là tooling (doc site, domain, git convention) hoặc quyết định kỹ thuật cần thiết trước khi code (JWT algorithm, DB diagram update)</li><li><strong>DA-559 gắn sai epic</strong> — nội dung là business-service data layer nhưng gắn vào E11 (API Gateway). Nên tách thành epic riêng hoặc sửa lại liên kết</li><li><strong>DA-410 (Google OMI API)</strong> cần xác nhận với Ân — tech stack gốc chọn Google Veo cho video gen, không phải Google OMI. Có thể là đánh giá thêm phương án, hoặc nhầm tên</li><li><strong>DA-561 lỗi chính tả prefix</strong> <code>Da-AI05-07</code> thay vì <code>DA-AI05-07</code> — không ảnh hưởng chức năng nhưng nên sửa cho nhất quán khi báo cáo/thống kê tự động</li></ul><hr><h2 id="_5-unassigned-backlog-—-172-tasks-breakdown-theo-epic" tabindex="-1">5. Unassigned backlog — 172 tasks, breakdown theo Epic <a class="header-anchor" href="#_5-unassigned-backlog-—-172-tasks-breakdown-theo-epic" aria-label="Permalink to &quot;5. Unassigned backlog — 172 tasks, breakdown theo Epic&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Epic</th><th>Unassigned</th><th>Nội dung</th></tr></thead><tbody><tr><td>AI03</td><td>8</td><td>RAG Knowledge Base Pipeline</td></tr><tr><td>AI04</td><td>8</td><td>LLM Content Generation</td></tr><tr><td>AI07</td><td>8</td><td>Virtual Brand Ambassador</td></tr><tr><td>E32</td><td>8</td><td>Publishing System</td></tr><tr><td>AI08</td><td>7</td><td>Image Composition Pipeline</td></tr><tr><td>AI05</td><td>6</td><td>Trend Crawler Service</td></tr><tr><td>AI11</td><td>6</td><td>AI Research Documentation</td></tr><tr><td>E40</td><td>6</td><td>Mobile App Core</td></tr><tr><td>E34</td><td>5</td><td>Design System</td></tr><tr><td>E23</td><td>5</td><td>AI Service Internal API Wiring</td></tr><tr><td>E36</td><td>5</td><td>Content Management Pages</td></tr><tr><td>E42</td><td>5</td><td>Testing</td></tr><tr><td>E15</td><td>5</td><td>Workspace Management</td></tr><tr><td>AI10</td><td>5</td><td>AI Service Integration &amp; Finalize</td></tr><tr><td>AI06</td><td>5</td><td>Image Generation Pipeline</td></tr><tr><td>E38</td><td>4</td><td>Analytics &amp; Reporting</td></tr><tr><td>E37</td><td>4</td><td>Client Portal</td></tr><tr><td>E44</td><td>4</td><td>Production Deployment</td></tr><tr><td>E35</td><td>4</td><td>Auth &amp; Dashboard Pages</td></tr><tr><td>E41</td><td>4</td><td>Mobile Notifications</td></tr><tr><td>E31</td><td>4</td><td>Approval Workflow</td></tr><tr><td>E46</td><td>4</td><td>Final Report &amp; Presentation</td></tr><tr><td>E45</td><td>4</td><td>Final Documentation</td></tr><tr><td>E19</td><td>4</td><td>TikTok/Threads/Zalo OAuth</td></tr><tr><td>E18</td><td>4</td><td>Meta OAuth</td></tr><tr><td>E17</td><td>4</td><td>Subscription &amp; Billing</td></tr><tr><td>E16</td><td>4</td><td>Client &amp; Agency Management</td></tr><tr><td>E14</td><td>4</td><td>RBAC</td></tr><tr><td>E30</td><td>4</td><td>Content Calendar &amp; Scheduling</td></tr><tr><td>E29</td><td>3</td><td>Task Assignment &amp; Tracking</td></tr><tr><td>E33</td><td>3</td><td>Publish Error Handling</td></tr><tr><td>E24</td><td>3</td><td>Business Service AI Integration</td></tr><tr><td>E22</td><td>3</td><td>Publish Callback &amp; Error Handling</td></tr><tr><td>E20</td><td>3</td><td>Token Lifecycle Management</td></tr><tr><td>E39</td><td>3</td><td>Notification System</td></tr><tr><td>E43</td><td>3</td><td>Bug Fixes &amp; Polish</td></tr><tr><td>E28</td><td>3</td><td>Content Request Management</td></tr></tbody></table><p><strong>Điểm khác biệt so với báo cáo lần 1:</strong> Unassigned trải đều qua hầu hết epic (3-8 task/epic), không tập trung riêng vào &quot;Phase 5-7&quot; như nhận định ban đầu. Kể cả epic Sprint 4-6 (E14-E20, đang gần với timeline hiện tại) cũng có 3-4 unassigned mỗi epic. <strong>Đây là vấn đề cấp bách hơn báo cáo lần 1 nhận định</strong> — vì cả những epic sắp tới (không chỉ epic xa) cũng thiếu người phụ trách.</p><hr><h2 id="_6-task-rac-loi-convention" tabindex="-1">6. Task rác / lỗi convention <a class="header-anchor" href="#_6-task-rac-loi-convention" aria-label="Permalink to &quot;6. Task rác / lỗi convention&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Key</th><th>Vấn đề</th><th>Đề xuất</th></tr></thead><tbody><tr><td>DA-562</td><td>Summary &quot;test slack&quot;, không phải task dự án</td><td>Xoá khỏi backlog</td></tr><tr><td>DA-561</td><td>Prefix <code>Da-AI05-07</code> sai case</td><td>Sửa thành <code>DA-AI05-07</code></td></tr><tr><td>DA-407</td><td>Prefix <code>DA-E010-07</code> — thừa số 0 (nên là E10 không phải E010)</td><td>Sửa lại prefix chuẩn</td></tr></tbody></table><hr><h2 id="_7-khoi-luong-cong-viec-hien-tai-—-đanh-gia-tong-the" tabindex="-1">7. Khối lượng công việc hiện tại — đánh giá tổng thể <a class="header-anchor" href="#_7-khoi-luong-cong-viec-hien-tai-—-đanh-gia-tong-the" aria-label="Permalink to &quot;7. Khối lượng công việc hiện tại — đánh giá tổng thể&quot;">​</a></h2><p><strong>Tiến độ chung:</strong> 14.3% Done, 11.3% In Review (gần xong chờ duyệt), 2% đang code → tổng cộng ~27.6% dự án đã có kết quả cụ thể hoặc gần xong. 42.4% chưa ai động vào.</p><p><strong>So với timeline dự án (32 tuần, hiện ở Sprint 3-4 = tuần 5-8):</strong> Ở mốc thời gian ~19-25% của tổng thời lượng dự án, tiến độ Done 14.3% không quá lệch pha — nhưng <strong>backlog unassigned lan rộng cả epic gần (Sprint 4-6)</strong> là dấu hiệu cần PM chủ động gán việc ngay, không đợi tới sprint đó mới làm.</p><p><strong>Điểm nghẽn tiềm ẩn:</strong></p><ul><li>Trung ôm 77 task (19% dự án) — nếu Trung là bottleneck review (13 task In Review + việc leader), các task khác chờ Trung duyệt sẽ dồn ứ</li><li>46 task In Review toàn dự án — cần biết trung bình đang chờ bao lâu, ai duyệt</li></ul><hr><h2 id="_8-viec-can-lam-ngay-theo-đo-uu-tien" tabindex="-1">8. Việc cần làm ngay (theo độ ưu tiên) <a class="header-anchor" href="#_8-viec-can-lam-ngay-theo-đo-uu-tien" aria-label="Permalink to &quot;8. Việc cần làm ngay (theo độ ưu tiên)&quot;">​</a></h2><ol><li><strong>Xoá <code>DA-562</code></strong>, sửa 2 lỗi convention (DA-561, DA-407)</li><li><strong>Assign 172 unassigned task</strong> — ưu tiên các epic gần timeline hiện tại trước (E14-E24, AI03-AI06), không chỉ epic xa</li><li><strong>Đồng bộ 10 task phát sinh vào <code>BrandHub_Task_Details.md</code></strong> — đặc biệt sửa epic gắn sai của DA-559</li><li><strong>Xác nhận với Ân</strong> — DA-410 (Google OMI API) có phải hướng nghiên cứu chính thức không, hay nhầm với Google Veo</li><li><strong>Check 46 task In Review</strong> — đo thời gian chờ duyệt trung bình, ai là bottleneck (Trung 13, Phước 11, Tuấn 11, Ân 8, Lộc 3)</li><li><strong>Theo dõi Ân</strong> — tỉ lệ Done 17.5% thấp nhất trong nhóm có việc từ đầu dự án</li></ol><hr><h2 id="rebalance-log-—-sau-sprint-4" tabindex="-1">Rebalance Log — sau Sprint 4 <a class="header-anchor" href="#rebalance-log-—-sau-sprint-4" aria-label="Permalink to &quot;Rebalance Log — sau Sprint 4&quot;">​</a></h2><p>&gt; Log quyết định tái phân bổ task, cho toàn team đọc để hiểu lý do thay đổi. Chi tiết task/sprint mới đã cập nhật trong <code>brandhub-master-plan.md</code> (đánh dấu 🔀).</p><h3 id="nguyen-nhan" tabindex="-1">Nguyên nhân <a class="header-anchor" href="#nguyen-nhan" aria-label="Permalink to &quot;Nguyên nhân&quot;">​</a></h3><p>Kế hoạch đổi: <strong>Lộc chuyển hẳn sang AI Sub-lead</strong>, không làm Frontend nữa — tập trung nghiên cứu thuật toán crawl + AI sinh nội dung cùng Tuấn/Ân. Vấn đề phát sinh: 25 task Frontend/Mobile (E34–E41) và 12 task AI-image (AI-06, AI-08) đang gán cho Lộc cần chuyển cho người khác.</p><h3 id="cac-phuong-an-đa-xet" tabindex="-1">Các phương án đã xét <a class="header-anchor" href="#cac-phuong-an-đa-xet" aria-label="Permalink to &quot;Các phương án đã xét&quot;">​</a></h3><table tabindex="0"><thead><tr><th>#</th><th>Phương án</th><th>Vì sao không chọn</th></tr></thead><tbody><tr><td>1</td><td>Chuyển 25 task Frontend cho Trung hoặc Phước &quot;học thêm&quot; React song song backend</td><td>Trung đã 61 task (nặng nhất team) — không dư sức. Cả Trung/Phước đều 100% Java trong plan, học React giữa dự án tăng rủi ro chất lượng cả 2 phía</td></tr><tr><td>2</td><td>Chia đều 25 task Frontend cho cả Trung + Phước</td><td>Không ai sở hữu trọn epic → dễ rời rạc, không ai chịu trách nhiệm UI xuyên suốt</td></tr><tr><td>3</td><td>Trung/Phước làm full-stack theo feature (code Java xong tự code UI luôn)</td><td>Hợp lý cho Trung (feature Trung có UI tương ứng), nhưng Phước (OAuth/RabbitMQ/publish adapter) không có UI riêng map trực tiếp → không áp dụng được toàn bộ</td></tr><tr><td>4</td><td><strong>Phước nhận full UI (có kinh nghiệm UI thật) + Trung phụ nhỏ khi cần</strong></td><td>✅ <strong>Chọn</strong> — Phước có nền UI, giải quyết đúng gốc rễ: ai đó cần sở hữu trọn Frontend/Mobile</td></tr></tbody></table><h3 id="giai-phap-cuoi-cung" tabindex="-1">Giải pháp cuối cùng <a class="header-anchor" href="#giai-phap-cuoi-cung" aria-label="Permalink to &quot;Giải pháp cuối cùng&quot;">​</a></h3><ol><li><strong>E34 (Design System) dời từ Sprint 12 → Sprint 5</strong> — làm ngay từ đầu, tránh Phước phải chờ đến Sprint 12 mới có component base trong khi vẫn đang cày Publisher ở Sprint 7–8, 11</li><li><strong>E35–E41 (toàn bộ Web Dashboard + Mobile App) chuyển từ Lộc → Phước</strong> — Phước vừa làm Publisher Service (đúng vị trí sprint gốc: S7, S8, S11) vừa làm UI (rải vào các sprint Publisher rảnh: S5–S6, S9, S12–S14), tránh dồn cụm 2 việc nặng cùng lúc</li><li><strong>AI-06 (Image Generation, 5 task) chuyển từ Lộc → Ân</strong> — cùng nhóm &quot;generative content&quot; với AI-09 (Video) Ân đang làm, quen sẵn pattern async + S3 upload</li><li><strong>AI-08 (Image Composition, 7 task) chuyển từ Lộc → Tuấn</strong> — cùng nhóm &quot;image pipeline&quot; với AI-07 (Ambassador) Tuấn đang làm</li><li><strong>E17 (Subscription &amp; Billing) dời từ Sprint 6 → Sprint 9</strong> — giảm tải Trung ở S5–S6 (25 task Auth+RBAC+Workspace+Client+Subscription dồn 2 sprint); Subscription không block gấp, S9 đang nhẹ (3 task)</li><li><strong>Review UI</strong>: không cần checkpoint riêng — Phước tự review + cả team chốt trạng thái In Review → Done trong buổi họp cuối mỗi sprint</li></ol><h3 id="tac-đong-khoi-luong-tong-task-khong-đoi-chi-đoi-nguoi-vi-tri" tabindex="-1">Tác động khối lượng (tổng task không đổi, chỉ đổi người/vị trí) <a class="header-anchor" href="#tac-đong-khoi-luong-tong-task-khong-đoi-chi-đoi-nguoi-vi-tri" aria-label="Permalink to &quot;Tác động khối lượng (tổng task không đổi, chỉ đổi người/vị trí)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Người</th><th>Trước</th><th>Sau</th><th>Thay đổi</th></tr></thead><tbody><tr><td>Trung</td><td>61</td><td>~63</td><td>+2 (không đáng kể, chỉ dời vị trí S5-S6→S9 để giảm đỉnh tải)</td></tr><tr><td>Phước</td><td>27</td><td>~52</td><td><strong>+25</strong> (nhận toàn bộ Frontend/Mobile)</td></tr><tr><td>Lộc</td><td>57</td><td>~33</td><td><strong>-24</strong> (rút hết Frontend, chỉ còn AI thuần)</td></tr><tr><td>Tuấn</td><td>22</td><td>~29</td><td>+7 (nhận AI-08)</td></tr><tr><td>Ân</td><td>33</td><td>~38</td><td>+5 (nhận AI-06)</td></tr></tbody></table><p><strong>Rủi ro cần theo dõi:</strong> Phước từ ít task nhất (27, cuối bảng) nhảy lên gần bằng Trung (~52 vs ~63) — tải tăng gần gấp đôi. Cần theo sát Sprint 5–6 (giai đoạn Phước vừa học Design System vừa chưa đụng Publisher) xem có kịp không.</p><hr><h2 id="_9-ghi-chu-phuong-phap" tabindex="-1">9. Ghi chú phương pháp <a class="header-anchor" href="#_9-ghi-chu-phuong-phap" aria-label="Permalink to &quot;9. Ghi chú phương pháp&quot;">​</a></h2><ul><li>Dữ liệu lấy qua Jira MCP <code>searchJiraIssuesUsingJql</code>, <code>ORDER BY key ASC</code>, phân trang qua <code>nextPageToken</code>, gộp toàn bộ 406/406 task (100% coverage — khác với audit lần 1 chỉ đọc được mẫu ~150/221 task unassigned)</li><li>Task ID đối chiếu bằng cách trích bracket <code>[DA-EXX-XX]</code> trong summary, so khớp với 415 task ID định nghĩa trong <code>BrandHub_Task_Details.md</code></li><li>Task cũ dạng DA-1 đến DA-144 không có bracket prefix trong summary nhưng khớp nội dung với plan — không tính là &quot;phát sinh&quot;, chỉ là quy ước đặt tên khác ở giai đoạn đầu</li><li>Không tính Subtask và Bug trong audit này</li></ul>',52)])])}const p=n(i,[["render",h]]);export{u as __pageData,p as default};
